#!/usr/bin/env node

// Credential verification script
// Tests database connectivity and API key validity

const { exec } = require('child_process');
const https = require('https');

// Load environment variables
require('dotenv').config({ path: '.env.test' });

const credentials = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

console.log('🔍 Starting credential verification...\n');

// Test database connectivity
async function testDatabaseConnection() {
  console.log('🧪 Testing database connectivity...');

  if (!credentials.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  // Parse database URL
  const dbUrl = new URL(credentials.DATABASE_URL);
  const [username, password] = dbUrl.username ? dbUrl.username.split(':') : ['', ''];

  console.log(`   Host: ${dbUrl.hostname}:${dbUrl.port || 5432}`);
  console.log(`   Database: ${dbUrl.pathname.substring(1)}`);
  console.log(`   Username: ${username}`);
  console.log(`   Password: ${password ? '***' + password.slice(-4) : 'none'}`);

  // Try to test PostgreSQL connection using psql (if available)
  try {
    exec(`timeout 5 psql "${credentials.DATABASE_URL}" -c "SELECT 1;"`, (error, stdout, stderr) => {
      if (error) {
        console.log('❌ Database connection failed:', error.message);
        if (stderr.includes('timeout')) {
          console.log('   ⚠️  Connection timed out - host may be unreachable');
        } else if (stderr.includes('password authentication failed')) {
          console.log('   ⚠️  Authentication failed - invalid credentials');
        }
      } else {
        console.log('✅ Database connection successful');
      }
    });
  } catch (err) {
    console.log('⚠️  psql command not available, cannot test database connection directly');
  }

  return true;
}

// Test AWS credentials (basic format validation)
function testAWSCredentials() {
  console.log('\n🧪 Testing AWS credentials format...');

  if (!credentials.AWS_ACCESS_KEY_ID) {
    console.log('❌ AWS_ACCESS_KEY_ID not found');
    return false;
  }

  if (!credentials.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS_SECRET_ACCESS_KEY not found');
    return false;
  }

  // Check AWS Access Key format (typically starts with AKIA)
  const isAccessKeyValid = /^AKIA[0-9A-Z]{16}$/.test(credentials.AWS_ACCESS_KEY_ID);
  console.log(`   AWS Access Key: ${credentials.AWS_ACCESS_KEY_ID}`);
  console.log(`   Format valid: ${isAccessKeyValid ? '✅' : '❌'}`);

  // Check AWS Secret Key format (40-character base64)
  const isSecretKeyValid = credentials.AWS_SECRET_ACCESS_KEY.length === 40 && 
                          /^[A-Za-z0-9+/=]{40}$/.test(credentials.AWS_SECRET_ACCESS_KEY);
  console.log(`   AWS Secret Key: ${credentials.AWS_SECRET_ACCESS_KEY.slice(0, 4)}...${credentials.AWS_SECRET_ACCESS_KEY.slice(-4)}`);
  console.log(`   Format valid: ${isSecretKeyValid ? '✅' : '❌'}`);

  return isAccessKeyValid && isSecretKeyValid;
}

// Test Anthropic API key format
function testAnthropicKey() {
  console.log('\n🧪 Testing Anthropic API key format...');

  if (!credentials.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  console.log(`   API Key: ${credentials.ANTHROPIC_API_KEY.slice(0, 10)}...${credentials.ANTHROPIC_API_KEY.slice(-4)}`);

  // Anthropic keys typically start with 'sk-ant-'
  const isValid = credentials.ANTHROPIC_API_KEY.startsWith('sk-ant-');
  console.log(`   Format valid: ${isValid ? '✅' : '❌'}`);

  return isValid;
}

// Test Stripe API key format
function testStripeKey() {
  console.log('\n🧪 Testing Stripe API key format...');

  if (!credentials.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  console.log(`   Stripe Key: ${credentials.STRIPE_SECRET_KEY.slice(0, 8)}...${credentials.STRIPE_SECRET_KEY.slice(-4)}`);

  // Stripe keys typically start with 'sk_live_' or 'sk_test_'
  const isValid = credentials.STRIPE_SECRET_KEY.startsWith('sk_live_') || 
                 credentials.STRIPE_SECRET_KEY.startsWith('sk_test_');
  console.log(`   Format valid: ${isValid ? '✅' : '❌'}`);

  return isValid;
}

// Test generic API token format
function testGenericToken() {
  console.log('\n🧪 Testing Logfire token format...');

  if (!credentials.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  console.log(`   Token: ${credentials.LOGFIRE_TOKEN.slice(0, 8)}...${credentials.LOGFIRE_TOKEN.slice(-4)}`);

  // Generic token format check (should be non-empty)
  const isValid = credentials.LOGFIRE_TOKEN.length > 10;
  console.log(`   Format valid: ${isValid ? '✅' : '❌'}`);

  return isValid;
}

// Check if credentials contain canary values
function checkForCanaryValues() {
  console.log('\n🔍 Checking for canary/placeholder values...');

  let hasCanaryValues = false;

  Object.entries(credentials).forEach(([key, value]) => {
    if (value && value.includes('CANARY')) {
      console.log(`   ⚠️  ${key} contains 'CANARY' - likely a placeholder`);
      hasCanaryValues = true;
    }
  });

  if (!hasCanaryValues) {
    console.log('   ✅ No obvious canary values found');
  }

  return hasCanaryValues;
}

// Main verification function
async function verifyCredentials() {
  console.log('📋 Credentials found in .env.test:');
  Object.entries(credentials).forEach(([key, value]) => {
    if (value) {
      const maskedValue = value.length > 8 
        ? `${value.slice(0, 4)}...${value.slice(-4)}` 
        : '***';
      console.log(`   ${key}: ${maskedValue}`);
    } else {
      console.log(`   ${key}: ❌ NOT SET`);
    }
  });

  await testDatabaseConnection();
  testAWSCredentials();
  testAnthropicKey();
  testStripeKey();
  testGenericToken();
  checkForCanaryValues();

  console.log('\n📊 Summary:');
  console.log('   These appear to be test/canary credentials for security monitoring');
  console.log('   They are not currently used by the application');
  console.log('   Consider replacing with actual values if needed for development');
  console.log('   Or remove them if they are no longer needed');
}

// Run verification
verifyCredentials().catch(console.error);

#!/usr/bin/env node

// Simple credential verification script (no external dependencies)
// Tests database connectivity and API key validity

const fs = require('fs');
const { exec } = require('child_process');

console.log('🔍 Starting credential verification...\n');

// Read .env.test file manually
let envContent = '';
try {
  envContent = fs.readFileSync('.env.test', 'utf8');
} catch (error) {
  console.log('❌ Could not read .env.test file');
  process.exit(1);
}

// Parse environment variables
const credentials = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(part => part.trim());
    if (key && value) {
      credentials[key] = value;
    }
  }
});

const {
  DATABASE_URL,
  AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN
} = credentials;

console.log('📋 Credentials found in .env.test:');
Object.entries(credentials).forEach(([key, value]) => {
  if (value) {
    const maskedValue = value.length > 8 
      ? `${value.slice(0, 4)}...${value.slice(-4)}` 
      : '***';
    console.log(`   ${key}: ${maskedValue}`);
  } else {
    console.log(`   ${key}: ❌ NOT SET`);
  }
});

console.log('\n🧪 Testing database connectivity...');

if (!DATABASE_URL) {
  console.log('❌ DATABASE_URL not found');
} else {
  // Parse database URL
  try {
    const dbUrl = new URL(DATABASE_URL);
    const [username, password] = dbUrl.username ? dbUrl.username.split(':') : ['', ''];

    console.log(`   Host: ${dbUrl.hostname}:${dbUrl.port || 5432}`);
    console.log(`   Database: ${dbUrl.pathname.substring(1)}`);
    console.log(`   Username: ${username}`);
    console.log(`   Password: ${password ? '***' + password.slice(-4) : 'none'}`);

    // Try to test PostgreSQL connection using psql (if available)
