#!/usr/bin/env node

// Credential validation script
// Tests connectivity and validity of environment variables from .env.test

require('dotenv').config({ path: '.env.test' });

const https = require('https');
const { Client } = require('pg');

// ANSI color codes for output
const colors = {
    red: '\x1b[31m',
    green: '\x1b[32m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    magenta: '\x1b[35m',
    cyan: '\x1b[36m',
    reset: '\x1b[0m'
};

function logResult(testName, status, message = '') {
    const statusColor = status === '✓' ? colors.green : 
                       status === '⚠' ? colors.yellow : colors.red;
    console.log(`${statusColor}${status}${colors.reset} ${testName.padEnd(25)} ${message}`);
}

async function testDatabaseConnection() {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
        logResult('DATABASE_URL', '✗', 'Not set');
        return false;
    }

    if (dbUrl.includes('CANARY')) {
        logResult('DATABASE_URL', '⚠', 'Contains CANARY placeholder - likely test value');
        return false;
    }

    try {
        const client = new Client({ connectionString: dbUrl });
        await client.connect();
        const result = await client.query('SELECT NOW() as current_time');
        await client.end();
        logResult('DATABASE_URL', '✓', `Connected successfully - ${result.rows[0].current_time}`);
        return true;
    } catch (error) {
        logResult('DATABASE_URL', '✗', `Connection failed: ${error.message}`);
        return false;
    }
}

async function testAWSKeys() {
    const accessKey = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
        logResult('AWS_KEYS', '✗', 'Missing one or both keys');
        return false;
    }

    if (accessKey.includes('CANARY') || secretKey.includes('CANARY')) {
        logResult('AWS_KEYS', '⚠', 'Contains CANARY placeholders - likely test values');
        return false;
    }

    // AWS keys have specific patterns we can validate
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

    const accessKeyValid = accessKeyPattern.test(accessKey);
    const secretKeyValid = secretKeyPattern.test(secretKey);

    if (accessKeyValid && secretKeyValid) {
        logResult('AWS_KEYS', '✓', 'Format appears valid (pattern matched)');
        return true;
    } else {
        logResult('AWS_KEYS', '✗', `Format validation failed - AccessKey: ${accessKeyValid}, SecretKey: ${secretKeyValid}`);
        return false;
    }
}

async function testAnthropicAPI() {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
        logResult('ANTHROPIC_API', '✗', 'Not set');
        return false;
    }

    if (apiKey.includes('CANARY')) {
        logResult('ANTHROPIC_API', '⚠', 'Contains CANARY placeholder - likely test value');
        return false;
    }

    // Anthropic API keys start with 'sk-ant-'
    if (apiKey.startsWith('sk-ant-')) {
        logResult('ANTHROPIC_API', '✓', 'Format appears valid (starts with sk-ant-)');
        return true;
    } else {
        logResult('ANTHROPIC_API', '✗', 'Invalid format - should start with "sk-ant-"');
        return false;
    }
}

async function testStripeAPI() {
    const stripeKey = process.env.STRIPE_SECRET_KEY;
    if (!stripeKey) {
        logResult('STRIPE_API', '✗', 'Not set');
        return false;
    }

    if (stripeKey.includes('CANARY')) {
        logResult('STRIPE_API', '⚠', 'Contains CANARY placeholder - likely test value');
        return false;
    }

    // Stripe keys start with 'sk_live_' or 'sk_test_'
    if (stripeKey.startsWith('sk_live_') || stripeKey.startsWith('sk_test_')) {
        logResult('STRIPE_API', '✓', 'Format appears valid (starts with sk_live_/sk_test_)');
        return true;
    } else {
        logResult('STRIPE_API', '✗', 'Invalid format - should start with "sk_live_" or "sk_test_"');
        return false;
    }
}

async function testLogfireToken() {
    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
        logResult('LOGFIRE_TOKEN', '✗', 'Not set');
        return false;
    }

    if (token.includes('CANARY')) {
        logResult('LOGFIRE_TOKEN', '⚠', 'Contains CANARY placeholder - likely test value');
        return false;
    }

    // Logfire tokens are typically UUID-like
    const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (uuidPattern.test(token)) {
        logResult('LOGFIRE_TOKEN', '✓', 'Format appears valid (UUID-like)');
        return true;
    } else {
        logResult('LOGFIRE_TOKEN', '⚠', 'Unusual format for a token');
        return false;
    }
}

async function main() {
    console.log(`${colors.cyan}🔍 Testing environment credentials from .env.test${colors.reset}\n`);

    // Test each credential
    await testDatabaseConnection();
    await testAWSKeys();
    await testAnthropicAPI();
    await testStripeAPI();
    await testLogfireToken();

    console.log(`\n${colors.cyan}📊 Summary:${colors.reset}`);
    console.log(`${colors.yellow}⚠  = Contains CANARY placeholder (likely test/debug value)`);
    console.log(`${colors.green}✓  = Format appears valid`);
    console.log(`${colors.red}✗  = Missing or invalid format`);
    console.log(`\n${colors.magenta}Note: This validation checks format patterns only.${colors.reset}`);
    console.log(`${colors.magenta}For full validation, actual API calls would be needed.${colors.reset}`);
}

// Handle uncaught errors
process.on('unhandledRejection', (error) => {
    console.error(`${colors.red}Unhandled rejection:${colors.reset}`, error);
    process.exit(1);
});

main().catch(console.error);

