#!/usr/bin/env node

// Simple credential validator - no external dependencies

const fs = require('fs');
const path = require('path');

// ANSI color codes for output
const colors = {
    red: '\x1b[31m',
    green: '\x1b[32m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    magenta: '\x1b[35m',
    cyan: '\x1b[36m',
    reset: '\x1b[0m'
};

function logResult(testName, status, message = '') {
    const statusColor = status === '✓' ? colors.green : 
                       status === '⚠' ? colors.yellow : colors.red;
    console.log(`${statusColor}${status}${colors.reset} ${testName.padEnd(25)} ${message}`);
}

function parseEnvFile(filePath) {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const envVars = {};

        content.split('\n').forEach(line => {
            line = line.trim();
            // Skip comments and empty lines
            if (!line || line.startsWith('#')) return;

            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.slice(0, equalsIndex).trim();
                const value = line.slice(equalsIndex + 1).trim();
                // Remove quotes if present
                envVars[key] = value.replace(/^['"]|['"]$/g, '');
            }
        });

        return envVars;
    } catch (error) {
        console.error(`${colors.red}Error reading .env.test:${colors.reset}`, error.message);
        return {};
    }
}

function testDatabaseConnection(dbUrl) {
    if (!dbUrl) {
        logResult('DATABASE_URL', '✗', 'Not set');
        return false;
    }

