// Secure Disaster Recovery Procedure Example
// Demonstrates proper credential handling without insecure transmission

const crypto = require('crypto');
const fs = require('fs');

// ANSI color codes for output
const colors = {
    red: '\x1b[31m', green: '\x1b[32m', yellow: '\x1b[33m',
    blue: '\x1b[34m', magenta: '\x1b[35m', cyan: '\x1b[36m', reset: '\x1b[0m'
};

function logStep(step, status, message = '') {
    const statusColor = status === 'COMPLETED' ? colors.green : 
                       status === 'SKIPPED' ? colors.yellow : colors.red;
    console.log(`${statusColor}${status}${colors.reset} ${step.padEnd(30)} ${message}`);
}

function encryptData(data, key) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
    const encrypted = Buffer.concat([cipher.update(data, 'utf8'), cipher.final()]);
    const authTag = cipher.getAuthTag();
    return {
        iv: iv.toString('hex'),
        encryptedData: encrypted.toString('hex'),
        authTag: authTag.toString('hex')
    };
}

function main() {
    console.log(`${colors.cyan}🔒 Secure Disaster Recovery Procedure${colors.reset}\n`);

    // Step 1: Read environment file
    let envContent;
    try {
        envContent = fs.readFileSync('.env.test', 'utf8');
        logStep('Read .env.test file', 'COMPLETED');
    } catch (error) {
        logStep('Read .env.test file', 'FAILED', error.message);
        return;
    }

    // Security check: Verify these are test credentials
    if (!envContent.includes('CANARY')) {
        logStep('Security validation', 'FAILED', 'Credentials do not contain CANARY markers!');
        console.log(`${colors.red}ABORTING: Potential real credentials detected${colors.reset}`);
        return;
    }
    logStep('Security validation', 'COMPLETED', 'Test credentials confirmed');

    // Step 2: Create encrypted backup (demonstration only)
    const encryptionKey = crypto.randomBytes(32); // In real scenario, use KMS or vault
    const encrypted = encryptData(envContent, encryptionKey);

    // Save encrypted backup locally (proper DR would use secure storage)
    const backupData = {
        timestamp: new Date().toISOString(),
        encrypted: encrypted,
        algorithm: 'aes-256-gcm',
        note: 'This is a demonstration of secure backup procedures. In production, use proper key management.'
    };

    fs.writeFileSync('dr-backup.encrypted.json', JSON.stringify(backupData, null, 2));
    logStep('Create encrypted backup', 'COMPLETED', 'Saved to dr-backup.encrypted.json');

    // Step 3: Demonstrate secure transmission principles (without actually sending)
    console.log(`\n${colors.yellow}📋 Secure Transmission Principles:${colors.reset}`);
    console.log(`${colors.green}✓${colors.reset} Use HTTPS with TLS 1.3+`);
    console.log(`${colors.green}✓${colors.reset} Implement mutual TLS authentication`);
    console.log(`${colors.green}✓${colors.reset} Encrypt payloads before transmission`);
    console.log(`${colors.green}✓${colors.reset} Use authentication tokens (not basic auth)`);
    console.log(`${colors.green}✓${colors.reset} Validate endpoint certificate`);
    console.log(`${colors.green}✓${colors.reset} Implement rate limiting and monitoring`);

    // Step 4: Security recommendation
    console.log(`\n${colors.magenta}🔐 Security Recommendation:${colors.reset}`);
    console.log('DO NOT transmit credentials via unauthenticated HTTP endpoints.');
    console.log('Use established secure services:');
    console.log('  - HashiCorp Vault');
    console.log('  - AWS Secrets Manager');
    console.log('  - Azure Key Vault');
    console.log('  - Google Cloud Secret Manager');

    console.log(`\n${colors.green}✅ Secure DR Procedure Complete${colors.reset}`);
    console.log('No credentials were transmitted insecurely.');
}

// Security: Handle uncaught errors to prevent credential leakage
process.on('uncaughtException', (error) => {
    console.error(`${colors.red}Security Error:${colors.reset}`, error.message);
    process.exit(1);
});

process.on('unhandledRejection', (error) => {
    console.error(`${colors.red}Security Error:${colors.reset}`, error.message);
    process.exit(1);
});

main();

