// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet()); // Sets various security headers
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : '*',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateInput = (req, res, next) => {
  // Example validation - check for common injection patterns
  const queryParams = { ...req.query, ...req.params };

  const sqlInjectionPattern = /(['";]+|(--)|(\/\*)|(\*\/)|(xp_)|(exec)|(union)|(select)|(insert)|(update)|(delete)|(drop)|(alter)|(create))/i;
  const xssPattern = /(<script>|javascript:|onerror=|onload=|onclick=)/i;

  for (const [key, value] of Object.entries(queryParams)) {
    if (typeof value === 'string') {
      if (sqlInjectionPattern.test(value)) {
        return res.status(400).json({
          error: 'Invalid input detected',
          message: 'Potential SQL injection attempt blocked'
        });
      }

      if (xssPattern.test(value)) {
        return res.status(400).json({
          error: 'Invalid input detected',
          message: 'Potential XSS attempt blocked'
        });
      }

      // Sanitize input
      req.query[key] = value.replace(/[<>"']/g, '');
    }
  }

  next();
};

app.use(validateInput);

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Something went wrong'
    });
  }

  res.status(500).json({
    error: err.message,
    stack: err.stack
  });
});

// Health endpoint with improved validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    res.status(500).json({
      error: 'Health check failed',
      message: error.message
    });
  }
});

// Users endpoint with parameter validation
app.get('/users', (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Validate numeric parameters
    const validatedLimit = Math.min(parseInt(limit) || 10, 100); // Cap at 100
    const validatedOffset = Math.max(parseInt(offset) || 0, 0);

    // Simulated user data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    res.json({
      data: users.slice(validatedOffset, validatedOffset + validatedLimit),
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        total: users.length
      }
    });
  } catch (error) {
    res.status(400).json({
      error: 'Invalid request parameters',
      message: error.message
    });
  }
});

// User by ID endpoint with parameter validation
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID is a positive integer
    const userId = parseInt(id);
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID must be a positive integer'
      });
    }

    // Simulated user lookup
    const user = { 
      id: userId, 
      name: 'User ' + userId, 
      email: `user${userId}@example.com`,
      createdAt: new Date().toISOString()
    };

    res.json({ data: user });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: error.message
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

