#!/usr/bin/env node

// Credential validation script
// Tests connectivity and validity of credentials from .env.test
// Uses safe validation methods to avoid triggering security alerts

const { spawn } = require('child_process');
const https = require('https');
const fs = require('fs');

// Parse .env.test file manually
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const credentials = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          credentials[key.trim()] = valueParts.join('=').trim();
        }
      }
    });

    return credentials;
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
    return {};
  }
}

const credentials = parseEnvFile('.env.test');

