// Test 4: Simple HTTP connectivity test (safe - no API calls)
async function testConnectivity() {
  console.log('\n4. Testing basic connectivity...');

  // Test multiple endpoints for better reliability
  const endpoints = [
    'https://httpbin.org/get',
    'https://www.example.com',
    'https://1.1.1.1'
  ];

  let connected = false;

  for (const endpoint of endpoints) {
    try {
      await new Promise((resolve, reject) => {
        const req = https.get(endpoint, { timeout: 3000 }, (res) => {
          res.destroy();
          resolve();
        }).on('error', (err) => {
          // Some errors are normal (like 404), but connection was established
          if (err.code !== 'ECONNREFUSED' && err.code !== 'EHOSTUNREACH') {
            resolve(); // Consider this a successful connection attempt
          } else {
            reject(err);
          }
        }).on('timeout', () => {
          req.destroy();
          reject(new Error('Timeout'));
        });
      });
      console.log(`   ✅ Connectivity to ${endpoint}: OK`);
      connected = true;
      break;
    } catch (error) {
      console.log(`   ⚠️  Connectivity to ${endpoint}: ${error.message}`);
      continue;
    }
  }

  if (!connected) {
    console.log('   ❌ No internet connectivity detected');
  }

  return connected;
}

