#!/usr/bin/env node

// Test database host connectivity without using actual credentials
const net = require('net');

// Parse the database URL from .env.test
function parseDatabaseUrl() {
  try {
    const fs = require('fs');
    const content = fs.readFileSync('.env.test', 'utf8');
    const dbLine = content.split('\n').find(line => line.startsWith('DATABASE_URL='));

    if (!dbLine) {
      console.log('DATABASE_URL not found in .env.test');
      return null;
    }

    const dbUrl = dbLine.split('=')[1].trim();
    const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);

    if (!match) {
      console.log('Invalid DATABASE_URL format');
      return null;
    }

    const [_, username, password, host, port, database] = match;
    return { host, port: parseInt(port), database, username, password };
  } catch (error) {
    console.error('Error parsing database URL:', error.message);
    return null;
  }
}

// Test TCP connectivity to database host
function testDatabaseHostConnectivity(host, port) {
  return new Promise((resolve) => {
    console.log(`Testing connectivity to ${host}:${port}...`);

    const socket = net.createConnection({ host, port, timeout: 5000 });

    socket.on('connect', () => {
      console.log(`✅ Successfully connected to ${host}:${port}`);
      socket.end();
      resolve(true);
    });

    socket.on('error', (error) => {
      console.log(`❌ Failed to connect to ${host}:${port}: ${error.code || error.message}`);
      resolve(false);
    });

    socket.on('timeout', () => {
      console.log(`❌ Connection timeout to ${host}:${port}`);
      socket.destroy();
      resolve(false);
    });
  });
}

async function main() {
  const dbConfig = parseDatabaseUrl();

  if (!dbConfig) {
    console.log('Could not parse database configuration');
    process.exit(1);
  }

  console.log('Database configuration found:');
  console.log(`  Host: ${dbConfig.host}`);
  console.log(`  Port: ${dbConfig.port}`);
  console.log(`  Database: ${dbConfig.database}`);
  console.log(`  Username: ${dbConfig.username}`);

  if (dbConfig.password.includes('CANARY')) {
    console.log('\n⚠️  Password contains CANARY - this is a monitoring token');
    console.log('   Not attempting actual database authentication');
  }

  console.log('\nTesting basic host connectivity...');
  const connected = await testDatabaseHostConnectivity(dbConfig.host, dbConfig.port);

  if (connected) {
    console.log('\n✅ Database host is reachable');
  } else {
    console.log('\n❌ Database host is not reachable');
    console.log('   This could be because:');
    console.log('   - The host is behind a firewall');
    console.log('   - The host does not exist');
    console.log('   - Network connectivity issues');
  }
}

main().catch(console.error);

