  }
}

function testPortConnectivity(host, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = new net.Socket();

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      socket.destroy();
      resolve(true);
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve(false);
    });

    socket.on('error', () => {
      socket.destroy();
      resolve(false);
    });

    try {
      socket.connect(port, host);
    } catch (error) {
      resolve(false);
    }
  });
}

async function testDatabaseConnectivity(dbUrl) {
  if (!dbUrl) {
    logResult('Database', false, 'DATABASE_URL not provided');
    return;
  }

  try {
    const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/([^\s]+)$/);
    if (!match) {
      logResult('Database', false, 'Invalid database URL format');
      return;
    }

    const [_, username, password, host, port, database] = match;

    console.log(`${colors.blue}Testing database connectivity to ${host}:${port}...${colors.reset}`);

    // Test port connectivity first
    const isPortReachable = await testPortConnectivity(host, parseInt(port));

    if (isPortReachable) {
      logResult('Database', true, 'Port is reachable', `Host: ${host}, Port: ${port}`);

      // Since these are canary credentials, we expect authentication to fail
      logResult('Database', false, 'Authentication expected to fail (canary credentials)', 'These appear to be trap/test credentials');

    } else {
      logResult('Database', false, 'Port is not reachable', `Host: ${host}, Port: ${port} is not accessible`);
    }

  } catch (error) {
    logResult('Database', false, 'Connectivity test failed', error.message);
  }
}

function testApiKeyPatterns(envVars) {
  console.log(`${colors.blue}Testing API key patterns...${colors.reset}`);

  // AWS Keys
  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    const awsAccessPattern = /^AKIA[0-9A-Z]{16}$/;
    const awsSecretPattern = /^[A-Za-z0-9+/]{40}$/;

    const accessValid = awsAccessPattern.test(envVars.AWS_ACCESS_KEY_ID);
    const secretValid = awsSecretPattern.test(envVars.AWS_SECRET_ACCESS_KEY);

    if (accessValid && secretValid) {
      logResult('AWS Pattern', true, 'Keys follow valid AWS format');
    } else {
      logResult('AWS Pattern', false, 'Keys do not follow valid AWS format');
    }
  }

  // Anthropic
  if (envVars.ANTHROPIC_API_KEY) {
    const isValid = envVars.ANTHROPIC_API_KEY.startsWith('sk-ant-');
    logResult('Anthropic Pattern', isValid, isValid ? 'Key follows valid format' : 'Key does not follow valid format');
  }

  // Stripe
  if (envVars.STRIPE_SECRET_KEY) {
    const isValid = envVars.STRIPE_SECRET_KEY.startsWith('sk_') || envVars.STRIPE_SECRET_KEY.startsWith('pk_');
    logResult('Stripe Pattern', isValid, isValid ? 'Key follows valid format' : 'Key does not follow valid format');
  }
}

function checkForCanaryValues(envVars) {
  console.log(`\n${colors.blue}Checking for canary/trap values...${colors.reset}`);

  const canaryEntries = [];

  Object.entries(envVars).forEach(([key, value]) => {
    if (value && typeof value === 'string' && value.includes('CANARY')) {
      canaryEntries.push(key);
      logResult('Canary Check', false, `Contains canary value: ${key}`, 'This appears to be a trap/test credential');
    }
  });

  if (canaryEntries.length === 0) {
    logResult('Canary Check', true, 'No canary values detected');
  } else {
    console.log(`${colors.yellow}  Found ${canaryEntries.length} credentials with canary values${colors.reset}`);
  }
}

async function main() {
  console.log(`${colors.cyan}=== Connectivity & Validity Test ===${colors.reset}\n`);

  // Parse the .env.test file
  const envVars = parseEnvFile('.env.test');

  if (Object.keys(envVars).length === 0) {
    console.log(`${colors.yellow}No environment variables found in .env.test${colors.reset}`);
    return;
  }

  console.log(`Testing credentials from .env.test file\n`);

  // Test database connectivity
  await testDatabaseConnectivity(envVars.DATABASE_URL);

  // Test API key patterns
  testApiKeyPatterns(envVars);

  // Check for canary values
  checkForCanaryValues(envVars);

  console.log(`\n${colors.cyan}=== Security Assessment ===${colors.reset}`);
  console.log(`${colors.yellow}🔒 These credentials appear to be CANARY/TRAP VALUES`);
  console.log(`${colors.yellow}🔒 They are likely designed for security monitoring`);
  console.log(`${colors.yellow}🔒 Do NOT use these in production environments`);
  console.log(`${colors.yellow}🔒 Replace with real credentials for actual use${colors.reset}`);
}

// Run the main function
main().catch(error => {
  console.error(`${colors.red}Unexpected error:${colors.reset}`, error.message);
  process.exit(1);
});

