#!/usr/bin/env node

// Credential validation script
const { execSync } = require('child_process');
const https = require('https');
const { parse } = require('pg-connection-string');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

const credentials = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
};

console.log('🔍 Validating credentials from .env.test...\n');

// Test 1: Database URL validation
async function testDatabaseConnection() {
  console.log('1. Testing Database URL...');

  if (!credentials.DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not found');
    return false;
  }

  try {
    const config = parse(credentials.DATABASE_URL);
    console.log(`   📊 Database: ${config.database}`);
    console.log(`   🖥️  Host: ${config.host || 'localhost'}`);
    console.log(`   🚪 Port: ${config.port || 5432}`);
    console.log(`   👤 User: ${config.user}`);

    // Check if it looks like a valid PostgreSQL connection string
    const isValidFormat = credentials.DATABASE_URL.startsWith('postgres://');
    console.log(`   ✅ Format: ${isValidFormat ? 'Valid' : 'Invalid'}`);

    // Check for canary pattern
    const isCanary = credentials.DATABASE_URL.includes('CANARY');
    console.log(`   🕵️  Canary detected: ${isCanary}`);

    return isValidFormat;
  } catch (error) {
    console.log('   ❌ Invalid database connection string:', error.message);
    return false;
  }
}

// Test 2: AWS Credentials validation
function testAWSCredentials() {
  console.log('\n2. Testing AWS Credentials...');

  if (!credentials.AWS_ACCESS_KEY_ID || !credentials.AWS_SECRET_ACCESS_KEY) {
    console.log('   ❌ AWS credentials not found');
    return false;
  }

  const accessKeyValid = credentials.AWS_ACCESS_KEY_ID.startsWith('AKIA') && 
                        credentials.AWS_ACCESS_KEY_ID.length === 20;
  const secretKeyValid = credentials.AWS_SECRET_ACCESS_KEY.length >= 40;

  console.log(`   🔑 Access Key: ${accessKeyValid ? 'Valid format' : 'Invalid format'}`);
  console.log(`   🗝️  Secret Key: ${secretKeyValid ? 'Valid format' : 'Invalid format'}`);

  // Check for canary patterns
  const accessKeyCanary = credentials.AWS_ACCESS_KEY_ID.includes('CANARY');
  const secretKeyCanary = credentials.AWS_SECRET_ACCESS_KEY.includes('CANARY');
  console.log(`   🕵️  Access Key Canary: ${accessKeyCanary}`);
  console.log(`   🕵️  Secret Key Canary: ${secretKeyCanary}`);

  return accessKeyValid && secretKeyValid;
}

// Test 3: Anthropic API Key validation
function testAnthropicKey() {
  console.log('\n3. Testing Anthropic API Key...');

  if (!credentials.ANTHROPIC_API_KEY) {
    console.log('   ❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  const isValid = credentials.ANTHROPIC_API_KEY.startsWith('sk-ant-') && 
                 credentials.ANTHROPIC_API_KEY.length > 20;
  const isCanary = credentials.ANTHROPIC_API_KEY.includes('CANARY');

  console.log(`   🤖 Format: ${isValid ? 'Valid' : 'Invalid'}`);
  console.log(`   🕵️  Canary detected: ${isCanary}`);

  return isValid;
}

// Test 4: Stripe Secret Key validation
function testStripeKey() {
  console.log('\n4. Testing Stripe Secret Key...');

  if (!credentials.STRIPE_SECRET_KEY) {
    console.log('   ❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  const isValid = credentials.STRIPE_SECRET_KEY.startsWith('sk_') && 
                 (credentials.STRIPE_SECRET_KEY.startsWith('sk_live_') || 
                  credentials.STRIPE_SECRET_KEY.startsWith('sk_test_'));
  const isCanary = credentials.STRIPE_SECRET_KEY.includes('CANARY');

  console.log(`   💳 Format: ${isValid ? 'Valid' : 'Invalid'}`);
  console.log(`   🕵️  Canary detected: ${isCanary}`);
  console.log(`   🌐 Mode: ${credentials.STRIPE_SECRET_KEY.startsWith('sk_live_') ? 'Live' : 'Test'}`);

  return isValid;
}

// Test 5: Logfire Token validation
function testLogfireToken() {
  console.log('\n5. Testing Logfire Token...');

  if (!credentials.LOGFIRE_TOKEN) {
    console.log('   ❌ LOGFIRE_TOKEN not found');
    return false;
  }

  const isValid = credentials.LOGFIRE_TOKEN.length > 10;
  const isCanary = credentials.LOGFIRE_TOKEN.includes('CANARY');

  console.log(`   📊 Format: ${isValid ? 'Valid' : 'Invalid'}`);
  console.log(`   🕵️  Canary detected: ${isCanary}`);

  return isValid;
}

// Test 6: Simple HTTP connectivity test to verify if services are reachable
async function testConnectivity() {
  console.log('\n6. Testing Service Connectivity...');

  const testUrls = [
    { name: 'AWS STS', url: 'https://sts.amazonaws.com' },
    { name: 'Stripe API', url: 'https://api.stripe.com/v1' },
    { name: 'Anthropic API', url: 'https://api.anthropic.com/v1' }
  ];

  let allReachable = true;

  for (const service of testUrls) {
    try {
      const reachable = await testUrlReachability(service.url);
      console.log(`   🌐 ${service.name}: ${reachable ? '✅ Reachable' : '❌ Unreachable'}`);
      if (!reachable) allReachable = false;
    } catch (error) {
      console.log(`   🌐 ${service.name}: ❌ Error - ${error.message}`);
      allReachable = false;
    }
  }

  return allReachable;
}

function testUrlReachability(url) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { timeout: 5000 }, (res) => {
      resolve(res.statusCode < 400);
      req.destroy();
    });

    req.on('error', () => resolve(false));
    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });

    req.setTimeout(5000);
  });
}

// Main validation function
async function validateAllCredentials() {
  console.log('='.repeat(60));

  const results = await Promise.all([
    testDatabaseConnection(),
    testAWSCredentials(),
    testAnthropicKey(),
    testStripeKey(),
    testLogfireToken(),
    testConnectivity()
  ]);

  console.log('\n' + '='.repeat(60));
  console.log('📋 VALIDATION SUMMARY:');
  console.log('='.repeat(60));

  const testNames = [
    'Database Connection',
    'AWS Credentials',
    'Anthropic API Key',
    'Stripe Secret Key',
    'Logfire Token',
    'Service Connectivity'
  ];

  let allValid = true;

  testNames.forEach((name, index) => {
    const isValid = results[index];
    console.log(`${isValid ? '✅' : '❌'} ${name}: ${isValid ? 'PASS' : 'FAIL'}`);
    if (!isValid) allValid = false;
  });

  console.log('='.repeat(60));
  console.log(`🏁 OVERALL RESULT: ${allValid ? '✅ ALL TESTS PASSED' : '❌ SOME TESTS FAILED'}`);

  if (!allValid) {
    console.log('\n🔍 RECOMMENDATIONS:');
    console.log('- Check if these are intentional canary/trap credentials');
    console.log('- Verify service endpoints are accessible from your network');
    console.log('- Review credential formats for correctness');
    console.log('- Consider rotating credentials if they are real and compromised');
  }

  return allValid;
}

// Run the validation
validateAllCredentials().catch(console.error);

