#!/usr/bin/env node

// Credential validation script
const https = require('https');
const fs = require('fs');

// Simple function to parse PostgreSQL connection string
function parsePostgresUrl(url) {
  if (!url) return null;

  try {
    // Remove postgres:// prefix
    const withoutPrefix = url.replace(/^postgres:\/\//, '');

    // Split user:password@host:port/database
    const parts = withoutPrefix.split('@');
    const userPass = parts[0].split(':');
    const hostDb = parts[1].split('/');
    const hostPort = hostDb[0].split(':');

    return {
      user: userPass[0],
      password: userPass[1] || '',
      host: hostPort[0],
      port: hostPort[1] || '5432',
      database: hostDb[1] || ''
    };
  } catch (error) {
    return null;
  }
}

// Load environment variables from .env.test manually
function loadEnvFile(path) {
  try {
    const content = fs.readFileSync(path, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, value] = line.split('=').map(part => part.trim());
        if (key && value) {
          envVars[key] = value;
        }
      }
    });

    return envVars;
  } catch (error) {
    console.log('❌ Could not load .env.test file');
    return {};
  }
}

