  console.log(`   📊 Format: ${isValid ? 'Valid' : 'Invalid'}`);
  console.log(`   🕵️  Canary detected: ${isCanary}`);

  return isValid;
}

// Test 6: Simple HTTP connectivity test to verify if services are reachable
async function testConnectivity() {
  console.log('\n6. Testing Service Connectivity...');

  const testUrls = [
    { name: 'AWS STS', url: 'https://sts.amazonaws.com' },
    { name: 'Stripe API', url: 'https://api.stripe.com/v1' },
    { name: 'Anthropic API', url: 'https://api.anthropic.com/v1' }
  ];

  let allReachable = true;

  for (const service of testUrls) {
