      allReachable = false;
    }
  }

  return allReachable;
}

function testUrlReachability(url) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { timeout: 5000 }, (res) => {
      resolve(res.statusCode < 400);
      req.destroy();
    });

    req.on('error', () => resolve(false));
    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });

    req.setTimeout(5000);
  });
}

