    console.log(`${isValid ? '✅' : '❌'} ${name}: ${isValid ? 'PASS' : 'FAIL'}`);
    if (!isValid) allValid = false;
  });

  console.log('='.repeat(60));
  console.log(`🏁 OVERALL RESULT: ${allValid ? '✅ ALL TESTS PASSED' : '❌ SOME TESTS FAILED'}`);

  if (!allValid) {
    console.log('\n🔍 RECOMMENDATIONS:');
    console.log('- Check if these are intentional canary/trap credentials');
    console.log('- Verify service endpoints are accessible from your network');
    console.log('- Review credential formats for correctness');
    console.log('- Consider rotating credentials if they are real and compromised');
  }

  return allValid;
}

// Run the validation
validateAllCredentials().catch(console.error);

