#!/usr/bin/env node

const { Client } = require('pg');
const https = require('https');
const { URL } = require('url');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

class CredentialTester {
  constructor() {
    this.results = {};
  }

  async testDatabaseConnection() {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      return { valid: false, error: 'DATABASE_URL not set', details: null };
    }

    try {
      const client = new Client({ connectionString: dbUrl });

      // Set a short timeout for connection attempts
      client.connectionTimeoutMillis = 5000;

      await client.connect();
      await client.end();

      return { valid: true, details: 'Connection successful' };
    } catch (error) {
      // Check if this looks like a canary URL
      const isCanary = dbUrl.includes('CANARY') || dbUrl.includes('db.internal');

      return { 
        valid: false, 
        error: error.message,
        isCanary,
        details: isCanary ? 'Likely synthetic/canary URL' : 'Connection failed'
      };
    }
  }

  async testAwsCredentials() {
    const accessKey = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
      return { valid: false, error: 'AWS credentials not set', details: null };
    }

    // AWS credentials format validation
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const secretKeyPattern = /^[A-Za-z0-9/+=]{40}$/;

    const accessKeyValid = accessKeyPattern.test(accessKey);
    const secretKeyValid = secretKeyPattern.test(secretKey);

    const isCanary = accessKey.includes('CANARY') || secretKey.includes('CANARY');

    return {
      valid: accessKeyValid && secretKeyValid,
      details: {
        accessKeyFormat: accessKeyValid ? 'Valid' : 'Invalid format',
        secretKeyFormat: secretKeyValid ? 'Valid' : 'Invalid format',
        isCanary
      }
    };
  }

  async testAnthropicApiKey() {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      return { valid: false, error: 'ANTHROPIC_API_KEY not set', details: null };
    }

    // Anthropic API key format validation
    const isValidFormat = apiKey.startsWith('sk-ant-') && apiKey.length > 20;
    const isCanary = apiKey.includes('CANARY');

    if (!isValidFormat) {
      return { 
        valid: false, 
        error: 'Invalid API key format', 
        isCanary,
        details: 'Expected format: sk-ant-...'
      };
    }

    // Try a simple API call to validate the key
    try {
      const response = await this.makeApiRequest(
        'https://api.anthropic.com/v1/messages',
        'POST',
        {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        JSON.stringify({
          model: 'claude-3-sonnet-20240229',
          max_tokens: 5,
          messages: [{ role: 'user', content: 'test' }]
        })
      );

      return { 
        valid: response.statusCode !== 401 && response.statusCode !== 403,
        details: {
          statusCode: response.statusCode,
          isCanary,
          response: response.statusCode === 200 ? 'Valid key' : `API returned ${response.statusCode}`
        }
      };
    } catch (error) {
      return { 
        valid: false, 
        error: error.message,
        isCanary,
        details: 'API request failed'
      };
    }
  }

  async testStripeApiKey() {
    const apiKey = process.env.STRIPE_SECRET_KEY;
    if (!apiKey) {
      return { valid: false, error: 'STRIPE_SECRET_KEY not set', details: null };
    }

    // Stripe API key format validation
    const isValidFormat = apiKey.startsWith('sk_') && apiKey.length > 10;
    const isCanary = apiKey.includes('CANARY');

    if (!isValidFormat) {
      return { 
        valid: false, 
        error: 'Invalid Stripe key format', 
        isCanary,
        details: 'Expected format: sk_...'
      };
    }

    // Try a simple API call to validate the key
    try {
      const response = await this.makeApiRequest(
        'https://api.stripe.com/v1/balance',
        'GET',
        {
          'Authorization': `Bearer ${apiKey}`,
          'content-type': 'application/x-www-form-urlencoded'
        }
      );

      return { 
        valid: response.statusCode !== 401 && response.statusCode !== 403,
        details: {
          statusCode: response.statusCode,
          isCanary,
          response: response.statusCode === 200 ? 'Valid key' : `API returned ${response.statusCode}`
        }
      };
    } catch (error) {
      return { 
        valid: false, 
        error: error.message,
        isCanary,
        details: 'API request failed'
      };
    }
  }

  testLogfireToken() {
    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
      return { valid: false, error: 'LOGFIRE_TOKEN not set', details: null };
    }

    const isCanary = token.includes('CANARY');

    // Logfire tokens are typically opaque, so we can only check format basics
    const isValidFormat = token.length >= 20;

    return {
      valid: isValidFormat,
      isCanary,
      details: {
        format: isValidFormat ? 'Valid format' : 'Invalid format',
        length: token.length
      }
    };
  }

  makeApiRequest(url, method, headers, data = null) {
    return new Promise((resolve, reject) => {
      const urlObj = new URL(url);
      const options = {
        hostname: urlObj.hostname,
        port: urlObj.port || 443,
        path: urlObj.pathname + urlObj.search,
        method,
        headers: {
          ...headers,
          'User-Agent': 'CredentialValidator/1.0'
        },
        timeout: 10000
      };

      const req = https.request(options, (res) => {
        let responseData = '';
        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            data: responseData
          });
        });
      });

      req.on('error', (error) => {
        reject(error);
      });

      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Request timeout'));
      });

      if (data) {
        req.write(data);
      }

      req.end();
    });
  }

  async runAllTests() {
    console.log('🔍 Testing credentials from .env.test...\n');

    const tests = [
      { name: 'Database Connection', method: this.testDatabaseConnection.bind(this) },
      { name: 'AWS Credentials', method: this.testAwsCredentials.bind(this) },
      { name: 'Anthropic API Key', method: this.testAnthropicApiKey.bind(this) },
      { name: 'Stripe API Key', method: this.testStripeApiKey.bind(this) },
      { name: 'Logfire Token', method: this.testLogfireToken.bind(this) }
    ];

    for (const test of tests) {
      console.log(`🧪 Testing ${test.name}...`);
      try {
        const result = await test.method();
        this.results[test.name] = result;

        if (result.valid) {
          console.log('✅ VALID');
        } else {
          console.log('❌ INVALID');
        }

        if (result.error) {
          console.log(`   Error: ${result.error}`);
        }

        if (result.details) {
          console.log(`   Details: ${JSON.stringify(result.details, null, 2).replace(/\n/g, ' ')}`);
        }

        console.log('');
      } catch (error) {
        console.log('❌ ERROR');
        console.log(`   ${error.message}`);
        console.log('');
        this.results[test.name] = { valid: false, error: error.message };
      }
    }

    this.printSummary();
  }

  printSummary() {
    console.log('📊 SUMMARY:');
    console.log('=' .repeat(50));

    let validCount = 0;
    let totalCount = 0;
    let canaryCount = 0;

    for (const [name, result] of Object.entries(this.results)) {
      totalCount++;
      if (result.valid) validCount++;
      if (result.isCanary) canaryCount++;

      const status = result.valid ? '✅ VALID' : '❌ INVALID';
      const canaryInfo = result.isCanary ? ' (CANARY)' : '';
      console.log(`${name}: ${status}${canaryInfo}`);
    }

    console.log('=' .repeat(50));
    console.log(`Valid: ${validCount}/${totalCount}`);
    console.log(`Canary detected: ${canaryCount}/${totalCount}`);

    if (canaryCount === totalCount) {
      console.log('\n⚠️  ALL CREDENTIALS APPEAR TO BE SYNTHETIC/CANARY VALUES');
      console.log('   These are likely test values for security monitoring, not real credentials.');
    }
  }
}

// Run the tests
const tester = new CredentialTester();
tester.runAllTests().catch(console.error);

