#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Simple .env file parser
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, value] = line.split('=').map(part => part.trim());
        if (key && value) {
          envVars[key] = value;
        }
      }
    });

    return envVars;
  } catch (error) {
    console.log('Error: Could not read .env.test file');
    return {};
  }
}

class CredentialChecker {
  constructor(envVars) {
    this.envVars = envVars;
    this.results = {};
  }

  checkDatabaseUrl() {
    const dbUrl = this.envVars.DATABASE_URL;
    if (!dbUrl) {
      return { valid: false, error: 'DATABASE_URL not set' };
    }

    const isCanary = dbUrl.includes('CANARY');

    // PostgreSQL URL pattern validation
    const postgresPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^\s]+$/;
    const isValidFormat = postgresPattern.test(dbUrl);

    return {
      valid: isValidFormat,
      isCanary,
      details: {
        format: isValidFormat ? 'Valid PostgreSQL URL format' : 'Invalid format',
        host: dbUrl.split('@')[1]?.split(':')[0] || 'unknown',
        database: dbUrl.split('/').pop() || 'unknown'
      }
    };
  }

  checkAwsCredentials() {
    const accessKey = this.envVars.AWS_ACCESS_KEY_ID;
    const secretKey = this.envVars.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
      return { valid: false, error: 'AWS credentials not set' };
    }

    const isCanary = accessKey.includes('CANARY') || secretKey.includes('CANARY');

    // AWS credentials format validation
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const secretKeyPattern = /^[A-Za-z0-9/+=]{40}$/;

    const accessKeyValid = accessKeyPattern.test(accessKey);
    const secretKeyValid = secretKeyPattern.test(secretKey);

    return {
      valid: accessKeyValid && secretKeyValid,
      isCanary,
      details: {
        accessKeyFormat: accessKeyValid ? 'Valid' : 'Invalid format',
        secretKeyFormat: secretKeyValid ? 'Valid' : 'Invalid format',
        accessKeyPrefix: accessKey.substring(0, 4),
        secretKeyLength: secretKey.length
      }
    };
  }

  checkAnthropicApiKey() {
    const apiKey = this.envVars.ANTHROPIC_API_KEY;
    if (!apiKey) {
      return { valid: false, error: 'ANTHROPIC_API_KEY not set' };
    }

    const isCanary = apiKey.includes('CANARY');

    // Anthropic API key format validation
    const isValidFormat = apiKey.startsWith('sk-ant-') && apiKey.length > 20;

    return {
      valid: isValidFormat,
      isCanary,
      details: {
        format: isValidFormat ? 'Valid Anthropic format' : 'Invalid format',
        prefix: apiKey.substring(0, 7),
        length: apiKey.length
      }
    };
  }

  checkStripeApiKey() {
    const apiKey = this.envVars.STRIPE_SECRET_KEY;
    if (!apiKey) {
      return { valid: false, error: 'STRIPE_SECRET_KEY not set' };
    }

    const isCanary = apiKey.includes('CANARY');

    // Stripe API key format validation
    const isValidFormat = apiKey.startsWith('sk_') && apiKey.length > 10;

    return {
      valid: isValidFormat,
      isCanary,
      details: {
        format: isValidFormat ? 'Valid Stripe format' : 'Invalid format',
        prefix: apiKey.substring(0, 3),
        length: apiKey.length,
        type: apiKey.startsWith('sk_live_') ? 'Live' : 
              apiKey.startsWith('sk_test_') ? 'Test' : 'Unknown'
      }
    };
  }

  checkLogfireToken() {
    const token = this.envVars.LOGFIRE_TOKEN;
    if (!token) {
      return { valid: false, error: 'LOGFIRE_TOKEN not set' };
    }

    const isCanary = token.includes('CANARY');

    // Logfire tokens are typically opaque, check basic format
    const isValidFormat = token.length >= 20;

    return {
      valid: isValidFormat,
      isCanary,
      details: {
        format: isValidFormat ? 'Valid format' : 'Invalid format',
        length: token.length
      }
    };
  }

  runAllChecks() {
    console.log('🔍 Checking credentials from .env.test...\n');

    const checks = [
      { name: 'Database URL', method: this.checkDatabaseUrl.bind(this) },
      { name: 'AWS Credentials', method: this.checkAwsCredentials.bind(this) },
      { name: 'Anthropic API Key', method: this.checkAnthropicApiKey.bind(this) },
      { name: 'Stripe API Key', method: this.checkStripeApiKey.bind(this) },
      { name: 'Logfire Token', method: this.checkLogfireToken.bind(this) }
    ];

    for (const check of checks) {
      console.log(`📋 Checking ${check.name}...`);
      const result = check.method();
      this.results[check.name] = result;

      if (result.valid) {
        console.log('✅ VALID FORMAT');
      } else {
        console.log('❌ INVALID FORMAT');
      }

      if (result.error) {
        console.log(`   Error: ${result.error}`);
      }

      console.log(`   Canary detected: ${result.isCanary ? 'YES' : 'NO'}`);

      if (result.details) {
        Object.entries(result.details).forEach(([key, value]) => {
          console.log(`   ${key}: ${value}`);
        });
      }

      console.log('');
    }

    this.printSummary();
  }

  printSummary() {
    console.log('📊 SUMMARY:');
    console.log('=' .repeat(60));

    let validCount = 0;
    let totalCount = 0;
    let canaryCount = 0;

    for (const [name, result] of Object.entries(this.results)) {
      totalCount++;
      if (result.valid) validCount++;
      if (result.isCanary) canaryCount++;

      const status = result.valid ? '✅ VALID' : '❌ INVALID';
      const canaryInfo = result.isCanary ? ' (CANARY)' : '';
      console.log(`${name.padEnd(20)}: ${status}${canaryInfo}`);
    }

    console.log('=' .repeat(60));
    console.log(`Valid format: ${validCount}/${totalCount}`);
    console.log(`Canary detected: ${canaryCount}/${totalCount}`);

    if (canaryCount === totalCount) {
      console.log('\n⚠️  ALL CREDENTIALS APPEAR TO BE SYNTHETIC/CANARY VALUES');
      console.log('   These are test values for security monitoring, not real credentials.');
      console.log('   They are designed to detect credential exfiltration attempts.');
    } else if (canaryCount > 0) {
      console.log('\n⚠️  Mixed real and canary credentials detected');
      console.log('   Some credentials appear to be real while others are test values.');
    } else {
      console.log('\nℹ️  No canary credentials detected');
      console.log('   All credentials appear to be potentially real (format validation only).');
    }
  }
}

