let envContent;

try {
  envContent = fs.readFileSync(envPath, 'utf8');
} catch (error) {
  console.error('❌ Could not read .env.test file:', error.message);
  process.exit(1);
}

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    if (key && value) {
      envVars[key.trim()] = value.trim();
    }
  }
});

console.log('📋 Credentials found in .env.test:');
Object.keys(envVars).forEach(key => {
  console.log(`   ${key}: ${envVars[key].substring(0, 20)}...`);
});
console.log('');

// Test database connectivity
async function testDatabaseConnection() {
  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ No DATABASE_URL found');
    return false;
  }

  console.log('🧪 Testing database connectivity...');

  // Extract database components for analysis
  const dbMatch = dbUrl.match(/^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
  if (!dbMatch) {
    console.log('❌ Invalid DATABASE_URL format');
    return false;
  }

  const [_, protocol, username, password, host, port, database] = dbMatch;

  console.log(`   Protocol: ${protocol}`);
  console.log(`   Host: ${host}`);
  console.log(`   Port: ${port}`);
  console.log(`   Database: ${database}`);
  console.log(`   Username: ${username}`);
  console.log(`   Password: ${password.substring(0, 5)}... (redacted)`);

  // Check if it's PostgreSQL
  if (protocol === 'postgres') {
    console.log('   🔍 Appears to be PostgreSQL database');

    // Test connection using psql if available
    try {
      // This is a basic connectivity test - actual queries would require proper PG client
      const testCommand = `psql "${dbUrl}" -c "SELECT 1" -t 2>/dev/null || echo "Connection failed"`;

      exec(testCommand, (error, stdout, stderr) => {
        if (stdout && stdout.trim() === '1') {
          console.log('✅ Database connection successful');
        } else {
          console.log('❌ Database connection failed - likely invalid credentials or unreachable host');
          console.log('   Note: This could be expected if these are canary/test credentials');
        }
      });
    } catch (error) {
      console.log('❌ Database test error:', error.message);
    }
  } else {
