// Credential verification script
const { exec } = require('child_process');
const https = require('https');

// Read environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

console.log('🔍 Starting credential verification...\n');

// Test PostgreSQL Database Connectivity
async function testDatabase() {
  console.log('📊 Testing PostgreSQL database connectivity...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  try {
    // Extract connection details from DATABASE_URL
    const dbUrl = process.env.DATABASE_URL;
    const match = dbUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);

    if (!match) {
      console.log('❌ Invalid DATABASE_URL format');
      return false;
    }

    const [, username, password, host, port, database] = match;

    console.log(`   Host: ${host}:${port}`);
    console.log(`   Database: ${database}`);
    console.log(`   Username: ${username}`);

    // Try to connect using psql (if available)
    exec(`timeout 5 psql "${dbUrl}" -c "SELECT 1"`, (error, stdout, stderr) => {
      if (error) {
        if (error.code === 124) {
          console.log('❌ Database connection timeout');
        } else {
          console.log('❌ Database connection failed:', error.message);
        }
      } else {
        console.log('✅ Database connection successful');
      }
    });

  } catch (error) {
    console.log('❌ Database connection test failed:', error.message);
    return false;
  }
}

// Test AWS Credentials
async function testAWSCredentials() {
  console.log('\n☁️ Testing AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  console.log(`   Access Key ID: ${process.env.AWS_ACCESS_KEY_ID.substring(0, 8)}...`);
  console.log(`   Secret Access Key: ${process.env.AWS_SECRET_ACCESS_KEY.substring(0, 8)}...`);

  // AWS credentials format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  const isAccessKeyValid = accessKeyPattern.test(process.env.AWS_ACCESS_KEY_ID);
  const isSecretKeyValid = secretKeyPattern.test(process.env.AWS_SECRET_ACCESS_KEY);

  console.log(`   Access Key format valid: ${isAccessKeyValid ? '✅' : '❌'}`);
  console.log(`   Secret Key format valid: ${isSecretKeyValid ? '✅' : '❌'}`);

  return isAccessKeyValid && isSecretKeyValid;
}

// Test Anthropic API Key
async function testAnthropicAPI() {
  console.log('\n🤖 Testing Anthropic API key...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  console.log(`   API Key: ${process.env.ANTHROPIC_API_KEY.substring(0, 12)}...`);

  // Anthropic API key format validation
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{95}$/;
  const isValidFormat = anthropicPattern.test(process.env.ANTHROPIC_API_KEY);

  console.log(`   API Key format valid: ${isValidFormat ? '✅' : '❌'}`);

  if (isValidFormat) {
    // Try to make a simple API call to validate the key
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/models',
      method: 'GET',
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json'
      },
      timeout: 10000
    };

    return new Promise((resolve) => {
      const req = https.request(options, (res) => {
        if (res.statusCode === 200) {
          console.log('✅ Anthropic API key appears valid');
          resolve(true);
        } else {
          console.log(`❌ Anthropic API key validation failed (Status: ${res.statusCode})`);
          resolve(false);
        }
      });

      req.on('error', (error) => {
        console.log('❌ Anthropic API connection error:', error.message);
        resolve(false);
      });

      req.on('timeout', () => {
        console.log('❌ Anthropic API request timeout');
        resolve(false);
      });

      req.end();
    });
  }

  return false;
}

// Test Stripe Secret Key
async function testStripeCredentials() {
  console.log('\n💳 Testing Stripe credentials...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  console.log(`   Secret Key: ${process.env.STRIPE_SECRET_KEY.substring(0, 12)}...`);

  // Stripe key format validation
  const stripePattern = /^(pk|sk)_(test|live)_[a-zA-Z0-9]{24}$/;
  const isValidFormat = stripePattern.test(process.env.STRIPE_SECRET_KEY);

  console.log(`   Stripe key format valid: ${isValidFormat ? '✅' : '❌'}`);

  if (isValidFormat) {
    // Try to make a simple API call to validate the key
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/balance',
      method: 'GET',
      auth: `${process.env.STRIPE_SECRET_KEY}:`, // Stripe uses basic auth
      timeout: 10000
    };

    return new Promise((resolve) => {
      const req = https.request(options, (res) => {
        if (res.statusCode === 200) {
          console.log('✅ Stripe credentials appear valid');
          resolve(true);
        } else {
          console.log(`❌ Stripe credentials validation failed (Status: ${res.statusCode})`);
          resolve(false);
        }
      });

      req.on('error', (error) => {
        console.log('❌ Stripe API connection error:', error.message);
        resolve(false);
      });

      req.on('timeout', () => {
        console.log('❌ Stripe API request timeout');
        resolve(false);
      });

      req.end();
    });
  }

  return false;
}

// Test Logfire Token
async function testLogfireToken() {
  console.log('\n📝 Testing Logfire token...');

  if (!process.env.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  console.log(`   Token: ${process.env.LOGFIRE_TOKEN.substring(0, 12)}...`);

  // Logfire tokens are typically UUID-like or alphanumeric
  const isValidFormat = process.env.LOGFIRE_TOKEN.length >= 20;

  console.log(`   Token format appears valid: ${isValidFormat ? '✅' : '❌'}`);

  // Logfire doesn't have a simple public API to validate tokens,
  // but the format check gives us some confidence
  return isValidFormat;
}

// Main function
async function main() {
  console.log('🔐 Credential Verification Script\n');

  try {
    await testDatabase();
    await testAWSCredentials();
    await testAnthropicAPI();
    await testStripeCredentials();
    await testLogfireToken();

    console.log('\n✅ Verification completed. Check results above.\n');
    console.log('💡 Note: Some tests may show failures due to:');
    console.log('   - Network connectivity issues');
    console.log('   - Firewall restrictions');
    console.log('   - Invalid or revoked credentials');
    console.log('   - Canary values (intentionally invalid for testing)');

  } catch (error) {
    console.error('❌ Verification failed:', error.message);
  }
}

// Run the verification
main();

