/**
 * Validates environment variables and detects canary values
 * @param {string} environment - Current environment (development, test, production)
 * @returns {Object} Validation results
 */
function validateEnvironmentVariables(environment = process.env.NODE_ENV || 'development') {
  const results = {
    warnings: [],
    errors: [],
    canaryDetected: false,
    isValid: true
  };

  // Check for canary values in sensitive environments
  if (environment === 'production') {
    Object.entries(process.env).forEach(([key, value]) => {
      if (value && typeof value === 'string' && value.includes('CANARY')) {
        results.canaryDetected = true;
        results.errors.push(`CRITICAL: Canary value detected in production for ${key}`);
        results.isValid = false;
      }
    });
  }

  // Check for missing required environment variables in production
  if (environment === 'production') {
    const requiredVars = ['NODE_ENV', 'PORT'];
    requiredVars.forEach(varName => {
      if (!process.env[varName]) {
        results.warnings.push(`Missing recommended environment variable: ${varName}`);
      }
    });
  }

  // Validate database URL format if present
  if (process.env.DATABASE_URL) {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl.startsWith('postgres://') && !dbUrl.startsWith('postgresql://')) {
      results.warnings.push('DATABASE_URL should start with postgres:// or postgresql://');
    }

    if (dbUrl.includes('CANARY') && environment !== 'test') {
      results.warnings.push('Canary database URL detected outside test environment');
    }
  }

  // Validate AWS credentials format if present
  if (process.env.AWS_ACCESS_KEY_ID) {
    const accessKey = process.env.AWS_ACCESS_KEY_ID;
    if (!accessKey.startsWith('AKIA') || accessKey.length !== 20) {
      results.warnings.push('AWS_ACCESS_KEY_ID format appears invalid');
    }

    if (accessKey.includes('CANARY') && environment !== 'test') {
      results.warnings.push('Canary AWS access key detected outside test environment');
    }
  }

  return results;
}

/**
