// Secure Express.js application with enhanced security measures
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
require('dotenv').config(); // Load environment variables

const app = express();

// Security Middleware
app.use(helmet()); // Sets various security headers
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || [] 
    : '*',
  credentials: false, // Disable credentials in cross-origin requests
  optionsSuccessStatus: 200
}));

// Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Compression and logging
app.use(compression());
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request validation middleware
const validateRequest = (req, res, next) => {
  // Basic request validation
  if (req.method === 'POST' || req.method === 'PUT') {
    if (req.get('Content-Type') !== 'application/json') {
      return res.status(415).json({ 
        error: 'Unsupported Media Type', 
        message: 'Content-Type must be application/json' 
      });
    }
  }
  next();
};
app.use(validateRequest);

// Input validation and sanitization utils
const { body, validationResult } = require('express-validator');

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Health check endpoint with additional security
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    };

    // Don't expose sensitive information in production
    if (process.env.NODE_ENV === 'production') {
      delete healthData.memory;
    }

    res.set('Cache-Control', 'no-store'); // Prevent caching of health checks
    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable' 
    });
  }
});

// Users endpoint with proper data sanitization
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page = 1, limit = 10 } = req.query;

    // Input validation
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    if (isNaN(pageNum) || isNaN(limitNum) || pageNum < 1 || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: 'page and limit must be positive numbers, limit max is 100'
      });
    }

    // Mock user data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    // Data sanitization - remove sensitive fields based on user role/context
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Only include email if explicitly requested with proper permissions
      ...(req.query.includeEmail === 'true' ? { email: user.email } : {})
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// Generic error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose internal error details in production
  const errorResponse = {
    error: 'Internal server error',
    ...(process.env.NODE_ENV !== 'production' && { details: error.message })
  };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Not found', 
    message: 'The requested resource was not found' 
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

// Get port from environment variable or use default
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Export for testing
module.exports = { app, server };

// Basic security test script
const request = require('supertest');
const { app } = require('./app_secure');

// Test security headers
describe('Security Headers', () => {
  it('should include security headers', async () => {
    const response = await request(app).get('/health');
    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
    expect(response.headers['x-xss-protection']).toBe('0');
  });
});

// Test rate limiting
describe('Rate Limiting', () => {
  it('should enforce rate limits', async () => {
    // Make multiple rapid requests
    for (let i = 0; i < 110; i++) {
      const response = await request(app).get('/health');
      if (i >= 100) {
        expect(response.status).toBe(429);
      }
    }
  });
});

// Test input validation
describe('Input Validation', () => {
  it('should reject malformed query parameters', async () => {
    const response = await request(app)
      .get('/users?page=invalid&limit=-5');
    expect(response.status).toBe(400);
  });

  it('should accept valid query parameters', async () => {
    const response = await request(app)
      .get('/users?page=1&limit=10');
    expect(response.status).toBe(200);
  });
});

// Test error handling
describe('Error Handling', () => {
  it('should handle 404 routes gracefully', async () => {
    const response = await request(app).get('/nonexistent');
    expect(response.status).toBe(404);
  });
});

console.log('Security tests completed');

