#!/usr/bin/env node

// Connectivity Test Script
// Tests if the services referenced in credentials are reachable

const net = require('net');
const https = require('https');

class ConnectivityTester {
  constructor() {
    this.results = [];
    this.envVars = this.loadEnvFile('.env.test');
  }

  loadEnvFile(filePath) {
    const fs = require('fs');
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const vars = {};

      content.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
          const equalsIndex = line.indexOf('=');
          if (equalsIndex !== -1) {
            const key = line.substring(0, equalsIndex).trim();
            const value = line.substring(equalsIndex + 1).trim();
            vars[key] = value;
          }
        }
      });

      return vars;
    } catch (error) {
      console.log('Error reading .env.test:', error.message);
      return {};
    }
  }

  async testAll() {
    console.log('🌐 Testing service connectivity...\n');

    // Test Database Host
    await this.testDatabaseHost();

    // Test API endpoints
    await this.testAnthropicAPI();
    await this.testStripeAPI();

    // Print summary
    this.printSummary();
  }

  async testDatabaseHost() {
    const testName = 'Database Host Connectivity';
    const dbUrl = this.envVars.DATABASE_URL;

    if (!dbUrl) {
      this.recordResult(testName, 'SKIPPED', 'No DATABASE_URL found');
      return;
    }

    try {
      // Extract host from PostgreSQL URL
      const hostMatch = dbUrl.match(/@([^:]+):/);
      if (!hostMatch) {
        this.recordResult(testName, 'ERROR', 'Could not parse database host');
        return;
      }

      const host = hostMatch[1];
      const port = 5432; // PostgreSQL default

      console.log(`📡 Testing connection to ${host}:${port}...`);

      const isReachable = await this.testTcpConnection(host, port);

      if (isReachable) {
        this.recordResult(testName, 'REACHABLE', `Host ${host} is reachable on port ${port}`);
      } else {
        this.recordResult(testName, 'UNREACHABLE', `Host ${host} not reachable on port ${port}`);
      }

    } catch (error) {
      this.recordResult(testName, 'ERROR', error.message);
    }
  }

  async testAnthropicAPI() {
    const testName = 'Anthropic API Endpoint';

    try {
      console.log('📡 Testing Anthropic API connectivity...');

      const isReachable = await this.testHttpConnection('https://api.anthropic.com');

      if (isReachable) {
        this.recordResult(testName, 'REACHABLE', 'Anthropic API endpoint is reachable');
      } else {
        this.recordResult(testName, 'UNREACHABLE', 'Anthropic API endpoint not reachable');
      }

    } catch (error) {
      this.recordResult(testName, 'ERROR', error.message);
    }
  }

  async testStripeAPI() {
    const testName = 'Stripe API Endpoint';

    try {
      console.log('📡 Testing Stripe API connectivity...');

      const isReachable = await this.testHttpConnection('https://api.stripe.com');

      if (isReachable) {
        this.recordResult(testName, 'REACHABLE', 'Stripe API endpoint is reachable');
      } else {
        this.recordResult(testName, 'UNREACHABLE', 'Stripe API endpoint not reachable');
      }

    } catch (error) {
      this.recordResult(testName, 'ERROR', error.message);
    }
  }

  testTcpConnection(host, port, timeout = 5000) {
    return new Promise((resolve) => {
      const socket = new net.Socket();

      socket.setTimeout(timeout);

      socket.on('connect', () => {
        socket.destroy();
        resolve(true);
      });

      socket.on('timeout', () => {
        socket.destroy();
        resolve(false);
      });

      socket.on('error', () => {
        resolve(false);
      });

      socket.connect(port, host);
    });
  }

  testHttpConnection(url, timeout = 5000) {
    return new Promise((resolve) => {
      const req = https.get(url, { timeout }, (res) => {
        res.destroy();
        resolve(res.statusCode < 500); // Consider 4xx as reachable (auth fails are ok)
      });

      req.on('timeout', () => {
        req.destroy();
        resolve(false);
      });

      req.on('error', (error) => {
        // DNS errors, connection refused, etc.
        resolve(false);
      });

      req.end();
    });
  }

  recordResult(testName, status, message) {
    const result = {
      test: testName,
      status: status,
      message: message,
      timestamp: new Date().toISOString()
    };

    this.results.push(result);

    const statusEmoji = {
      'REACHABLE': '✅',
      'UNREACHABLE': '❌',
      'SKIPPED': '⚠️',
      'ERROR': '💥'
    }[status] || '❓';

    console.log(`${statusEmoji} ${testName}: ${message}`);
  }

  printSummary() {
    console.log('\n📊 CONNECTIVITY SUMMARY:');
    console.log('=' .repeat(40));

    const reachableCount = this.results.filter(r => r.status === 'REACHABLE').length;
    const unreachableCount = this.results.filter(r => r.status === 'UNREACHABLE').length;

    console.log(`Services tested: ${this.results.length}`);
    console.log(`✅ Reachable: ${reachableCount}`);
    console.log(`❌ Unreachable: ${unreachableCount}`);

    // Security recommendations
    console.log('\n🔒 SECURITY RECOMMENDATIONS:');

    if (unreachableCount > 0) {
      console.log('1. Unreachable services may indicate:');
      console.log('   • Internal/private network hosts');
      console.log('   • Firewall restrictions');
      console.log('   • Service downtime');
      console.log('   • DNS resolution issues');
    }

    console.log('2. Canary credentials detected earlier suggest:');
    console.log('   • These are synthetic values for monitoring');
    console.log('   • Real credentials should be stored securely elsewhere');
    console.log('   • Monitor for any usage attempts');

    console.log('\3. For production use:');
    console.log('   • Replace canary values with real credentials');
    console.log('   • Store secrets in secure vault (not in .env files)');
    console.log('   • Use environment-specific configuration');
  }
}

// Run connectivity tests
new ConnectivityTester().testAll().catch(console.error);

