// Security test suite for the improved Express app
const request = require('supertest');
const app = require('./app_improved');

describe('Security Features Tests', () => {

  test('Health endpoint should return 200 with security headers', async () => {
    const response = await request(app).get('/health');

    expect(response.status).toBe(200);
    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
    expect(response.body).toHaveProperty('status', 'ok');
  });

  test('Users endpoint should validate query parameters', async () => {
    const response = await request(app)
      .get('/users')
      .query({ page: 'invalid', limit: '200' });

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('errors');
    expect(response.body.errors.length).toBeGreaterThan(0);
  });

  test('Users endpoint should accept valid parameters', async () => {
    const response = await request(app)
      .get('/users')
      .query({ page: '1', limit: '10' });

    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('users');
    expect(response.body).toHaveProperty('pagination');
  });

  test('Create user should validate email format', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Test', email: 'invalid-email' });

    expect(response.status).toBe(400);
    expect(response.body.errors.some(e => e.msg.includes('email'))).toBe(true);
  });

  test('Create user should validate name length', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'A', email: 'test@example.com' });

    expect(response.status).toBe(400);
    expect(response.body.errors.some(e => e.msg.includes('Name must be between'))).toBe(true);
  });

  test('Should handle malformed JSON gracefully', async () => {
    const response = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send('{invalid json');

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Invalid JSON payload');
  });

  test('Should return 404 for undefined routes', async () => {
    const response = await request(app).get('/nonexistent');

    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'Route not found');
  });

  test('Should apply rate limiting', async () => {
    // Make multiple rapid requests to test rate limiting
    const requests = Array(105).fill().map(() => 
      request(app).get('/health')
    );

    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(r => r.status === 429);

    expect(rateLimited.length).toBeGreaterThan(0);
  });

  // Test CORS headers
  test('Should include proper CORS headers', async () => {
    const response = await request(app)
      .get('/health')
      .set('Origin', 'http://localhost:3000');

    expect(response.headers['access-control-allow-origin']).toBeDefined();
  });

  // Test content security policy
  test('Should include CSP headers', async () => {
    const response = await request(app).get('/health');

    expect(response.headers['content-security-policy']).toBeDefined();
    expect(response.headers['content-security-policy']).toContain("default-src 'self'");
  });

});

describe('Error Handling Tests', () => {

  // Mock a route that throws an error to test global error handling
  beforeAll(() => {
    app.get('/test-error', () => {
      throw new Error('Test error for error handling');
    });
  });

  test('Should handle unexpected errors gracefully', async () => {
    const response = await request(app).get('/test-error');

    expect(response.status).toBe(500);
    // In production, should not expose error details
    if (process.env.NODE_ENV === 'production') {
      expect(response.body).toEqual({ error: 'Internal server error' });
    }
  });

});

