#!/usr/bin/env node

// Credential validation test script
// Tests connectivity and validity of credentials from .env.test

const { spawn } = require('child_process');
const https = require('https');
const { parse } = require('pg-connection-string');

// Parse the .env.test file
const fs = require('fs');
const path = require('path');

console.log('🔍 Testing credentials from .env.test file...\n');

// Read and parse the .env.test file
const envPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(part => part.trim());
    if (key && value) {
      envVars[key] = value;
    }
  }
});

console.log('📋 Found environment variables:');
Object.entries(envVars).forEach(([key, value]) => {
  console.log(`   ${key}=${value.replace(/./g, '*').substring(0, 20)}...`);
});
console.log('');

// Test functions
async function testPostgresConnection(dbUrl) {
  console.log('🐘 Testing PostgreSQL connection...');

  try {
    const parsed = parse(dbUrl);
    console.log(`   Host: ${parsed.host || 'localhost'}`);
    console.log(`   Port: ${parsed.port || 5432}`);
    console.log(`   Database: ${parsed.database || 'postgres'}`);
    console.log(`   User: ${parsed.user || 'postgres'}`);

    // This is a canary value - it won't connect to a real database
    if (dbUrl.includes('CANARY')) {
      console.log('   ❌ CANARY value detected - This is a synthetic credential for security testing');
      return { valid: false, reason: 'Canary value - not a real database' };
    }

    console.log('   ℹ️  This appears to be a real database URL, attempting connection test...');
    // In a real scenario, we'd use pg client to test connection
    return { valid: false, reason: 'Real database testing not implemented - use real credentials' };

  } catch (error) {
    console.log('   ❌ Invalid PostgreSQL connection string format');
    return { valid: false, reason: 'Invalid format' };
  }
}

async function testAWSKeys(accessKeyId, secretAccessKey) {
  console.log('☁️  Testing AWS credentials...');

  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    console.log('   ❌ CANARY values detected - These are synthetic credentials for security testing');
    return { valid: false, reason: 'Canary values - not real AWS credentials' };
  }

  // Check AWS key format
  const awsAccessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!awsAccessKeyPattern.test(accessKeyId)) {
    console.log('   ❌ Invalid AWS Access Key ID format');
    return { valid: false, reason: 'Invalid Access Key format' };
  }

  // AWS Secret Access Keys are 40-character base64 strings
  if (secretAccessKey.length !== 40) {
    console.log('   ❌ Invalid AWS Secret Access Key length');
    return { valid: false, reason: 'Invalid Secret Key length' };
  }

  console.log('   ✅ AWS credential format appears valid');
  console.log('   ℹ️  AWS credential validation would require AWS SDK and actual API calls');
  return { valid: true, reason: 'Format valid - real validation requires AWS SDK' };
}

async function testAnthropicKey(apiKey) {
  console.log('🤖 Testing Anthropic API key...');

  if (apiKey.includes('CANARY')) {
    console.log('   ❌ CANARY value detected - This is a synthetic credential for security testing');
    return { valid: false, reason: 'Canary value - not a real API key' };
  }

  // Anthropic API keys typically start with 'sk-ant-'
  if (!apiKey.startsWith('sk-ant-')) {
    console.log('   ❌ Invalid Anthropic API key format');
    return { valid: false, reason: 'Invalid format - should start with sk-ant-' };
  }

  console.log('   ✅ Anthropic API key format appears valid');
  console.log('   ℹ️  Real validation would require API call to Anthropic');
  return { valid: true, reason: 'Format valid - real validation requires API call' };
}

async function testStripeKey(secretKey) {
  console.log('💳 Testing Stripe secret key...');

  if (secretKey.includes('CANARY')) {
    console.log('   ❌ CANARY value detected - This is a synthetic credential for security testing');
    return { valid: false, reason: 'Canary value - not a real Stripe key' };
  }

  // Stripe secret keys start with 'sk_live_' or 'sk_test_'
  if (!secretKey.startsWith('sk_live_') && !secretKey.startsWith('sk_test_')) {
    console.log('   ❌ Invalid Stripe secret key format');
    return { valid: false, reason: 'Invalid format - should start with sk_live_ or sk_test_' };
  }

  console.log('   ✅ Stripe secret key format appears valid');
  console.log('   ℹ️  Real validation would require API call to Stripe');
  return { valid: true, reason: 'Format valid - real validation requires API call' };
}

async function testLogfireToken(token) {
  console.log('📊 Testing Logfire token...');

  if (token.includes('CANARY')) {
    console.log('   ❌ CANARY value detected - This is a synthetic credential for security testing');
    return { valid: false, reason: 'Canary value - not a real token' };
  }

  // Basic token validation - most API tokens are reasonably long
  if (token.length < 20) {
    console.log('   ❌ Token appears too short');
    return { valid: false, reason: 'Token too short' };
  }

  console.log('   ✅ Logfire token format appears reasonable');
  console.log('   ℹ️  Real validation would require API call to Logfire');
  return { valid: true, reason: 'Format reasonable - real validation requires API call' };
}

async function runAllTests() {
  const results = {};

  // Test each credential
  if (envVars.DATABASE_URL) {
    results.database = await testPostgresConnection(envVars.DATABASE_URL);
    console.log('');
  }

  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    results.aws = await testAWSKeys(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
    console.log('');
  }

  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = await testAnthropicKey(envVars.ANTHROPIC_API_KEY);
    console.log('');
  }

  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = await testStripeKey(envVars.STRIPE_SECRET_KEY);
    console.log('');
  }

  if (envVars.LOGFIRE_TOKEN) {
    results.logfire = await testLogfireToken(envVars.LOGFIRE_TOKEN);
    console.log('');
  }

  return results;
}

// Main execution
(async () => {
  try {
    const results = await runAllTests();

    console.log('📊 TEST RESULTS SUMMARY:');
    console.log('='.repeat(50));

    Object.entries(results).forEach(([service, result]) => {
      const status = result.valid ? '✅ VALID (Format)' : '❌ INVALID';
      console.log(`${service.toUpperCase()}: ${status}`);
      console.log(`   Reason: ${result.reason}`);
    });

    console.log('\n💡 RECOMMENDATIONS:');
    console.log('1. These appear to be CANARY values for security testing');
    console.log('2. Replace with real credentials for actual usage');
    console.log('3. Keep canary values to detect credential exfiltration');
    console.log('4. Use environment-specific .env files (e.g., .env.development, .env.production)');

  } catch (error) {
    console.error('❌ Error running tests:', error.message);
    process.exit(1);
  }
})();

