// Enhanced application with comprehensive security measures
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
const { v4: uuidv4 } = require('uuid');

const app = express();

// Security Middleware Setup

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// 2. CORS configuration (adjust origins as needed)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parser with size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging middleware
app.use((req, res, next) => {
  req.requestId = uuidv4();
  console.log(`${new Date().toISOString()} - ${req.requestId} - ${req.method} ${req.path}`);
  next();
});

// Custom validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array(),
      requestId: req.requestId
    });
  }
  next();
};

// Routes with improved security

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.requestId
  });
});

app.get('/users', 
  // Input validation
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
  ],
  validateRequest,
  (req, res) => {
    try {
      const { page = 1, limit = 10 } = req.query;

      // Sample users data (in production, this would come from a secure database)
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          // Never expose sensitive data like passwords in responses
          createdAt: new Date('2023-01-01').toISOString()
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          createdAt: new Date('2023-01-02').toISOString()
        },
      ];

      // Apply pagination (sanitized inputs)
      const startIndex = (parseInt(page) - 1) * parseInt(limit);
      const endIndex = startIndex + parseInt(limit);
      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: users.length,
          totalPages: Math.ceil(users.length / parseInt(limit))
        },
        requestId: req.requestId
      });
    } catch (error) {
      console.error(`Error in /users route: ${error.message}`, { requestId: req.requestId });
      res.status(500).json({
        error: 'Internal server error',
        requestId: req.requestId
      });
    }
  }
);

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    requestId: req.requestId
  });
});

// Global Error Handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error, { requestId: req.requestId });

  // Don't expose internal error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { error: 'Internal server error', requestId: req.requestId }
    : { error: error.message, stack: error.stack, requestId: req.requestId };

  res.status(500).json(errorResponse);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

