#!/usr/bin/env node

// Credential validation script
// Tests connectivity and validity of credentials in .env.test

require('dotenv').config({ path: '.env.test' });

const https = require('https');
const { Client } = require('pg');

async function testDatabaseConnection() {
  console.log('\n🔍 Testing Database Connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL,
    connectionTimeoutMillis: 5000,
    ssl: { rejectUnauthorized: false }
  });

  try {
    await client.connect();
    const result = await client.query('SELECT NOW() as current_time');
    console.log('✅ Database connection successful');
    console.log(`   Current database time: ${result.rows[0].current_time}`);
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

async function testAWSKeys() {
  console.log('\n🔍 Testing AWS Credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  // AWS credentials follow specific patterns
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  const accessKeyValid = accessKeyPattern.test(process.env.AWS_ACCESS_KEY_ID);
  const secretKeyValid = secretKeyPattern.test(process.env.AWS_SECRET_ACCESS_KEY);

  if (accessKeyValid && secretKeyValid) {
    console.log('✅ AWS credential format appears valid');
    console.log(`   Access Key: ${process.env.AWS_ACCESS_KEY_ID.substring(0, 8)}...`);
    console.log(`   Secret Key: ${process.env.AWS_SECRET_ACCESS_KEY.substring(0, 8)}...`);
    return true;
  } else {
    console.log('❌ AWS credential format invalid');
    if (!accessKeyValid) console.log('   Invalid Access Key format');
    if (!secretKeyValid) console.log('   Invalid Secret Key format');
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\n🔍 Testing Anthropic API Key...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  // Anthropic API key pattern validation
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{95}$/;

  if (anthropicPattern.test(process.env.ANTHROPIC_API_KEY)) {
    console.log('✅ Anthropic API key format appears valid');
    console.log(`   Key: ${process.env.ANTHROPIC_API_KEY.substring(0, 15)}...`);

    // Try a simple API call to validate
    try {
      const response = await makeAPIRequest('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        body: JSON.stringify({
          model: 'claude-3-sonnet-20240229',
          max_tokens: 5,
          messages: [{ role: 'user', content: 'Hello' }]
        })
      });

      if (response.status === 401) {
        console.log('❌ Anthropic API key is invalid (unauthorized)');
        return false;
      } else if (response.status === 200 || response.status === 400) {
        console.log('✅ Anthropic API key appears valid (got expected response)');
        return true;
      } else {
        console.log(`⚠️  Anthropic API returned unexpected status: ${response.status}`);
        return false;
      }
    } catch (error) {
      console.log(`❌ Anthropic API test failed: ${error.message}`);
      return false;
    }
  } else {
    console.log('❌ Anthropic API key format invalid');
    return false;
  }
}

async function testStripeAPI() {
  console.log('\n🔍 Testing Stripe API Key...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  // Stripe API key pattern validation
  const stripePattern = /^(sk_(live|test)_[a-zA-Z0-9]{24})$/;

  if (stripePattern.test(process.env.STRIPE_SECRET_KEY)) {
    console.log('✅ Stripe API key format appears valid');
    console.log(`   Key: ${process.env.STRIPE_SECRET_KEY.substring(0, 10)}...`);

    // Try a simple API call to validate
    try {
      const response = await makeAPIRequest('https://api.stripe.com/v1/balance', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`
        }
      });

      if (response.status === 401) {
        console.log('❌ Stripe API key is invalid (unauthorized)');
        return false;
      } else if (response.status === 200) {
        console.log('✅ Stripe API key appears valid');
        return true;
      } else {
        console.log(`⚠️  Stripe API returned unexpected status: ${response.status}`);
        return false;
      }
    } catch (error) {
      console.log(`❌ Stripe API test failed: ${error.message}`);
      return false;
    }
  } else {
    console.log('❌ Stripe API key format invalid');
    return false;
  }
}

async function testLogfireToken() {
  console.log('\n🔍 Testing Logfire Token...');

  if (!process.env.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  console.log('✅ Logfire token found (validation would require specific Logfire API)');
  console.log(`   Token: ${process.env.LOGFIRE_TOKEN.substring(0, 10)}...`);
  return true; // Cannot validate without specific API endpoint
}

function makeAPIRequest(url, options) {
  return new Promise((resolve, reject) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, data }));
    });

    req.on('error', reject);

    if (options.body) {
      req.write(options.body);
    }

    req.end();
  });
}

async function main() {
  console.log('🚀 Starting credential validation...');
  console.log('=' .repeat(50));

  const results = {
    database: await testDatabaseConnection(),
    aws: await testAWSKeys(),
    anthropic: await testAnthropicAPI(),
    stripe: await testStripeAPI(),
    logfire: await testLogfireToken()
  };

  console.log('\n' + '=' .repeat(50));
  console.log('📊 Validation Results:');
  console.log('=' .repeat(50));

  Object.entries(results).forEach(([service, valid]) => {
    console.log(`${valid ? '✅' : '❌'} ${service.toUpperCase()}: ${valid ? 'VALID' : 'INVALID'}`);
  });

  const allValid = Object.values(results).every(result => result);
  console.log('\n' + '=' .repeat(50));
  console.log(allValid ? '🎉 All credentials appear valid!' : '⚠️  Some credentials may be invalid or stale');

  if (!allValid) {
    console.log('\n🔒 Recommendation: Replace any invalid credentials with valid ones');
    console.log('   or remove them from the environment file if not needed.');
  }
}

main().catch(console.error);

